@import "./themes/light.css";
@import "./themes/dark.css";
@import "./syntax.css";

:root {
  color-scheme: light dark;
  --bg: #f4f6f8;
  --bg-elevated: #ffffff;
  --fg: #0f172a;
  --fg-muted: #64748b;
  --panel: #f8fafc;
  --border: #e2e8f0;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --accent-soft: #dbeafe;
  --editor-cursor-color: #1d4ed8;
  --danger: #b91c1c;
  --radius: 10px;
  --shadow: 0 1px 2px rgb(15 23 42 / 6%), 0 8px 24px rgb(15 23 42 / 6%);
  --font: "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "SF Mono", Menlo, monospace;
}

.theme-dark {
  --bg: #0b1220;
  --bg-elevated: #111827;
  --fg: #e5e7eb;
  --fg-muted: #94a3b8;
  --panel: #0f172a;
  --border: #1e293b;
  --accent: #3b82f6;
  --accent-hover: #60a5fa;
  --accent-soft: #1e3a5f;
  --editor-cursor-color: #f9e2af;
  --shadow: 0 1px 2px rgb(0 0 0 / 40%), 0 12px 32px rgb(0 0 0 / 35%);
}

@media (prefers-color-scheme: dark) {
  .theme-auto {
    --bg: #0b1220;
    --bg-elevated: #111827;
    --fg: #e5e7eb;
    --fg-muted: #94a3b8;
    --panel: #0f172a;
    --border: #1e293b;
    --accent: #3b82f6;
    --accent-hover: #60a5fa;
    --accent-soft: #1e3a5f;
    --editor-cursor-color: #f9e2af;
    --shadow: 0 1px 2px rgb(0 0 0 / 40%), 0 12px 32px rgb(0 0 0 / 35%);
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--fg);
  line-height: 1.45;
}

button,
input,
select {
  font: inherit;
}

.app {
  display: flex;
  flex-direction: column;
  min-height: 100%;
  height: 100%;
}

/* Top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  flex-wrap: wrap;
  padding: 0.55rem 1rem;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 2;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 8px;
  background: linear-gradient(145deg, var(--accent), #7c3aed);
  color: white;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.brand strong {
  display: block;
  font-size: 0.95rem;
}

.brand-sub {
  display: block;
  color: var(--fg-muted);
  font-size: 0.75rem;
}

.topbar-actions {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  justify-content: flex-end;
}

/* View mode: Markdown | Formatado | Dividida (TabNews-style) */
.view-toggle {
  display: inline-flex;
  align-items: stretch;
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
  background: var(--panel);
  flex-shrink: 0;
}

.view-toggle-btn {
  border: none;
  background: transparent;
  color: var(--fg-muted);
  padding: 0.4rem 0.9rem;
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

.view-toggle-btn + .view-toggle-btn {
  border-left: 1px solid var(--border);
}

.view-toggle-btn:hover {
  color: var(--fg);
  background: var(--bg-elevated);
}

.view-toggle-btn.is-active {
  background: var(--accent);
  color: #fff;
}

/* Workspace grid */
.workspace {
  display: grid;
  grid-template-columns: var(--left-width, 240px) minmax(0, 1fr) var(--right-width, 240px);
  flex: 1;
  min-height: 0;
  transition: grid-template-columns 0.15s ease;
}

.workspace.left-collapsed {
  grid-template-columns: 44px minmax(0, 1fr) var(--right-width, 240px);
}

.workspace.right-collapsed {
  grid-template-columns: var(--left-width, 240px) minmax(0, 1fr) 44px;
}

.workspace.left-collapsed.right-collapsed {
  grid-template-columns: 44px minmax(0, 1fr) 44px;
}

.panel {
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 0.85rem;
  overflow: auto;
  min-height: 0;
}

.panel.right {
  border-right: 0;
  border-left: 1px solid var(--border);
}

.panel.rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0.5rem 0.25rem;
  overflow: hidden;
}

.rail-btn {
  width: 2rem;
  height: 2rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg-elevated);
  cursor: pointer;
  font-size: 0.95rem;
  line-height: 1;
}

.rail-btn:hover {
  border-color: var(--accent);
  background: var(--accent-soft);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.panel h2 {
  margin: 0;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-muted);
  font-weight: 700;
}

.workspace-badge {
  max-width: 9rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.center {
  display: grid;
  min-width: 0;
  min-height: 0;
  background: var(--bg);
}

/* Side-by-side when split — full height each column */
.center.mode-split {
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr;
}

.center.mode-source,
.center.mode-preview {
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
}

@media (max-width: 900px) {
  .center.mode-split {
    grid-template-columns: 1fr;
    grid-template-rows: 1fr 1fr;
  }

  .workspace,
  .workspace.left-collapsed,
  .workspace.right-collapsed,
  .workspace.left-collapsed.right-collapsed {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto 1fr auto;
  }

  .panel.left,
  .panel.right,
  .panel.rail {
    max-height: 28vh;
  }
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.55rem 0.75rem;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.875rem;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--fg);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
}

.btn-sm {
  padding: 0.4rem 0.7rem;
  font-size: 0.8rem;
}

.btn-icon {
  font-size: 1rem;
  line-height: 1;
}

.open-actions {
  display: grid;
  gap: 0.5rem;
  margin-bottom: 0.85rem;
}

.open-actions .btn {
  width: 100%;
}

/* Fields */
.field {
  display: grid;
  gap: 0.3rem;
  margin-bottom: 0.75rem;
  font-size: 0.8rem;
  color: var(--fg-muted);
}

.field input,
.field select,
.card select {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.5rem 0.65rem;
  background: var(--bg-elevated);
  color: var(--fg);
}

.field input:focus,
.field select:focus,
.card select:focus {
  outline: 2px solid color-mix(in srgb, var(--accent) 45%, transparent);
  border-color: var(--accent);
}

/* Banners / empty */
.banner {
  margin: 0 0 0.75rem;
  padding: 0.55rem 0.65rem;
  border-radius: 8px;
  font-size: 0.78rem;
  line-height: 1.4;
}

.banner code {
  font-family: var(--mono);
  font-size: 0.72rem;
}

.banner-info {
  background: var(--accent-soft);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--border));
}

.banner-muted {
  background: var(--bg-elevated);
  color: var(--fg-muted);
  border: 1px solid var(--border);
}

.empty-state {
  padding: 1.25rem 0.5rem;
  text-align: center;
  color: var(--fg-muted);
  font-size: 0.85rem;
}

.empty-state .muted {
  opacity: 0.85;
  font-size: 0.8rem;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.15rem;
  margin-bottom: 0.65rem;
  padding: 0.35rem 0.4rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.78rem;
}

.crumb {
  border: none;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  padding: 0.15rem 0.3rem;
  border-radius: 4px;
  font-weight: 600;
}

.crumb:hover:not(:disabled) {
  background: var(--accent-soft);
}

.crumb:disabled,
.crumb.is-current {
  color: var(--fg);
  cursor: default;
}

.crumb-sep {
  color: var(--fg-muted);
  user-select: none;
}

.crumb-up {
  margin-left: auto;
}

.file-meta {
  margin-left: auto;
  font-size: 0.7rem;
  color: var(--fg-muted);
}

.file-item.is-dir .file-name {
  font-weight: 600;
}

/* File list */
.file-list-wrap {
  min-height: 8rem;
}

.file-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.25rem;
}

.file-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  text-align: left;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg);
  border-radius: 8px;
  padding: 0.45rem 0.5rem;
  cursor: pointer;
}

.file-item:hover {
  background: var(--bg-elevated);
  border-color: var(--border);
}

.file-item.is-active {
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  color: var(--accent);
  font-weight: 600;
}

.file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Editor / preview — same footprint in the center column */
.editor,
.preview {
  min-height: 0;
  min-width: 0;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.center.mode-split .editor {
  border-right: 1px solid var(--border);
  border-bottom: 0;
}

.center.mode-split .preview {
  border-bottom: 0;
}

.editor header,
.code-block header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.75rem;
  border-bottom: 1px solid var(--border);
  background: var(--panel);
  font-size: 0.8rem;
  color: var(--fg-muted);
}

.editor-host {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.editor .cm-editor {
  height: 100%;
  font-size: var(--editor-font-size, 14px);
  line-height: var(--editor-line-height, 1.5);
}

.editor .cm-scroller {
  font-family: var(--editor-font-family, var(--mono));
  height: 100%;
}

.editor .cm-content {
  caret-color: var(--editor-cursor-color, var(--accent));
}

.editor .cm-cursor,
.editor .cm-dropCursor {
  border-left: 2px solid var(--editor-cursor-color, var(--accent)) !important;
  filter: drop-shadow(0 0 1px var(--bg-elevated));
}

.preview {
  overflow: hidden;
}

/* Full width of center pane (matches Markdown editor area) */
.preview-body {
  font-family: var(--preview-font-family, inherit);
  font-size: var(--preview-font-size, 16px);
  flex: 1;
  min-height: 0;
  min-width: 0;
  box-sizing: border-box;
  padding: 1.5rem 2rem 3rem;
  overflow: auto;
  width: 100%;
  max-width: none;
  margin: 0;
  scroll-behavior: smooth;
}

/* Keep line length readable only on ultra-wide centers without shrinking the pane */
.center.mode-preview .preview-body {
  padding-left: clamp(1.25rem, 3vw, 2.5rem);
  padding-right: clamp(1.25rem, 3vw, 2.5rem);
}

.preview-body h1,
.preview-body h2,
.preview-body h3,
.preview-body h4,
.preview-body h5,
.preview-body h6 {
  line-height: 1.25;
  scroll-margin-top: 0.75rem;
}

.outline ul {
  list-style: none;
  padding-left: 0;
}

.outline-link {
  display: block;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  padding: 0.2rem 0.25rem;
  border-radius: 4px;
  font-size: 0.85rem;
  line-height: 1.35;
}

.outline-link:hover {
  background: var(--accent-soft);
  text-decoration: underline;
}

.outline-empty {
  margin: 0.4rem 0 0;
  font-size: 0.8rem;
  color: var(--fg-muted);
}

.settings-hint {
  margin: 0.35rem 0 0;
  font-size: 0.72rem;
  color: var(--fg-muted);
  line-height: 1.35;
}

.preview-body pre {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  overflow: auto;
  max-width: 100%;
}

.preview-body code {
  font-family: var(--mono);
  font-size: 0.88em;
}

.preview-body table {
  width: 100%;
  border-collapse: collapse;
  display: block;
  overflow-x: auto;
  max-width: 100%;
}

.preview-body img,
.preview-body video {
  max-width: 100%;
  height: auto;
}

.preview-body p,
.preview-body li {
  max-width: none;
}

.preview-body .wiki-link {
  border-radius: 0.25rem;
  padding: 0 0.15rem;
  text-decoration: none;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, transparent);
}

.preview-body .wiki-link.is-unresolved,
.preview-body .wiki-link.is-ambiguous {
  color: var(--text-secondary);
  text-decoration: underline dashed;
  text-underline-offset: 0.2em;
}

.wiki-unresolved-notice {
  position: absolute;
  right: 1rem;
  bottom: 1rem;
  z-index: 5;
  display: flex;
  gap: 0.75rem;
  align-items: center;
  padding: 0.65rem 0.8rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  color: var(--fg);
  background: var(--bg-elevated);
  box-shadow: var(--shadow);
}

.wiki-completion-menu {
  position: absolute;
  z-index: 12;
  left: 1rem;
  bottom: 1rem;
  width: min(26rem, calc(100% - 2rem));
  max-height: 18rem;
  overflow: auto;
  padding: 0.35rem;
  border: 1px solid var(--border);
  border-radius: 0.5rem;
  background: var(--bg-elevated);
  box-shadow: var(--shadow);
}

.wiki-completion-menu button {
  display: flex;
  width: 100%;
  gap: 0.75rem;
  justify-content: space-between;
  padding: 0.5rem 0.6rem;
  border: 0;
  border-radius: 0.35rem;
  color: var(--fg);
  background: transparent;
  text-align: left;
}

.wiki-completion-menu button.is-selected,
.wiki-completion-menu button:hover {
  background: var(--accent-soft);
}

.wiki-completion-menu small {
  overflow: hidden;
  color: var(--fg-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Right cards */
.card,
.outline,
.panel.right > section {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem;
  margin-bottom: 0.75rem;
}

.outline ul,
.diag-list {
  margin: 0.4rem 0 0;
  padding-left: 1.1rem;
  font-size: 0.85rem;
}

.diag-list {
  list-style: disc;
  color: var(--fg-muted);
}

.panel.right label {
  display: grid;
  gap: 0.25rem;
  margin-top: 0.5rem;
  font-size: 0.8rem;
  color: var(--fg-muted);
}

@media (max-width: 960px) {
  .workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }
  .panel.right {
    border-left: 0;
    border-top: 1px solid var(--border);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }

  .editor .cm-focused > .cm-scroller > .cm-cursorLayer {
    opacity: 1 !important;
    animation: none !important;
  }
}
